package segtree

import "testing"

func TestSegTreeBuild(t *testing.T) {
	st := New([]int{1, 2, 3, 4, 5})
	if st.Query(0, 4) != 15 {
		t.Fatalf("want 15 got %d", st.Query(0, 4))
	}
}

func TestSegTreeRangeQuery(t *testing.T) {
	st := New([]int{1, 3, 5, 7, 9})
	if st.Query(1, 3) != 15 { // 3+5+7
		t.Fatalf("want 15 got %d", st.Query(1, 3))
	}
	if st.Query(0, 0) != 1 {
		t.Fatalf("want 1 got %d", st.Query(0, 0))
	}
}

func TestSegTreeUpdate(t *testing.T) {
	st := New([]int{1, 2, 3, 4, 5})
	st.Update(2, 10) // change index 2 from 3 to 10
	if st.Query(0, 4) != 22 { // 1+2+10+4+5
		t.Fatalf("want 22 got %d", st.Query(0, 4))
	}
}

func TestSegTreeSingleElement(t *testing.T) {
	st := New([]int{42})
	if st.Query(0, 0) != 42 {
		t.Fatalf("want 42 got %d", st.Query(0, 0))
	}
	st.Update(0, 10)
	if st.Query(0, 0) != 10 {
		t.Fatalf("want 10 got %d", st.Query(0, 0))
	}
}

func TestSegTreeMultiUpdate(t *testing.T) {
	st := New([]int{0, 0, 0, 0})
	for i := 0; i < 4; i++ {
		st.Update(i, i+1)
	}
	if st.Query(0, 3) != 10 { // 1+2+3+4
		t.Fatalf("want 10 got %d", st.Query(0, 3))
	}
}

